import React from "react";

type TableState = "available" | "selected" | "reserved";

interface TableNodeProps {
  id: string;
  state: TableState;
  onClick?: () => void;
}

export function TableNode({ id, state, onClick }: TableNodeProps) {
  const isAvailable = state === "available";
  const isSelected = state === "selected";
  const isReserved = state === "reserved";

  return (
    <div
      className="flex flex-col items-center gap-2 cursor-pointer"
      onClick={onClick}
    >
      <div className="relative flex items-center justify-center p-3">
        {/* Seats representation */}
        <div
          className={`absolute -top-1 w-3 h-3 rounded-full border ${isSelected ? "border-dashed border-gold-accent" : isAvailable ? "border-green-primary" : "border-border bg-field"}`}
        />
        <div
          className={`absolute -bottom-1 w-3 h-3 rounded-full border ${isSelected ? "border-dashed border-gold-accent" : isAvailable ? "border-green-primary" : "border-border bg-field"}`}
        />
        <div
          className={`absolute -left-1 w-3 h-3 rounded-full border ${isSelected ? "border-dashed border-gold-accent" : isAvailable ? "border-green-primary" : "border-border bg-field"}`}
        />
        <div
          className={`absolute -right-1 w-3 h-3 rounded-full border ${isSelected ? "border-dashed border-gold-accent" : isAvailable ? "border-green-primary" : "border-border bg-field"}`}
        />

        {/* Main Table Circle */}
        <div
          className={`w-12 h-12 rounded-full flex items-center justify-center font-inter font-semibold text-[14px] transition-all ${
            isSelected
              ? "bg-green-primary text-text shadow-[0_0_0_2px_#e5ad3c]"
              : isAvailable
                ? "bg-green-deep text-text border border-green-primary"
                : "bg-field text-text-muted border border-border"
          }`}
        >
          {id}
        </div>
      </div>
      <span className="font-inter text-[13px] text-text-muted capitalize">
        {state === "reserved" ? "Reserved (gray)" : state}
      </span>
    </div>
  );
}
